fn put (& self , key : & [u8] , value : & [u8]) -> Box < Future < Item = () , Error = Error > > { let mut opts = Options :: new () ; opts . create_if_missing = true ; let db = match LDatabase :: open (Path :: new (& * self . path) , opts) { Ok (db) => Box :: new (db) , Err (e) => { panic ! ("failed to open database: {:?}" , e) } } ; let write_opts = WriteOptions :: new () ; match db . put (write_opts , key , value) { Ok (_) => { return finished (()) . boxed () } , Err (e) => { return failed (Error :: LevelDBError (e)) . boxed () } } }